import XCTest
@testable import SheepdogKit

/// The daemon's wire, as the Go side writes it (`testdata/protocol/`,
/// generated by `internal/web/protocol_golden_test.go`): every file must
/// decode with the app's own types, and what the app sends must survive a
/// decode and encode unchanged. A daemon change the app cannot read fails
/// here, not on a phone.
///
/// The files are read from the source tree (`#filePath`), which the
/// simulator can reach; nothing is bundled.
final class ProtocolGoldenTests: XCTestCase {
    /// testdata/protocol, four levels up from this file
    /// (ios/Tests/SheepdogKitTests/ProtocolGoldenTests.swift).
    static let root: URL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent().deletingLastPathComponent()
        .deletingLastPathComponent().deletingLastPathComponent()
        .appendingPathComponent("testdata/protocol")

    /// Every golden this test expects, so a missing directory or a file
    /// the Go side stopped writing fails instead of passing on nothing.
    static let expected: [String: [String]] = [
        "ws/server": ["bot-ready", "card-approval", "card-markdown", "error", "error-account", "flush", "pong",
                      "screen", "screen-error", "status", "status-closed", "transcript-in", "transcript-out"],
        "ws/client": ["cancel", "client-ready", "drain", "mute", "ping", "playback", "screen-subscribe",
                      "screen-unsubscribe", "silence", "speaking", "text", "visibility"],
        "term/server": ["term-closed", "term-error", "term-free", "term-opened", "term-ready"],
        "term/client": ["term-close", "term-hello", "term-mouse", "term-open", "term-open-shell", "term-resize", "term-scroll"],
        "rest": ["hello", "state"],
    ]

    private func goldens(_ dir: String) throws -> [(name: String, data: Data)] {
        let url = Self.root.appendingPathComponent(dir)
        let names = try FileManager.default.contentsOfDirectory(atPath: url.path)
            .filter { $0.hasSuffix(".json") }
            .map { String($0.dropLast(5)) }
            .sorted()
        XCTAssertEqual(names, Self.expected[dir]?.sorted(), "testdata/protocol/\(dir)")
        return try names.map { ($0, try Data(contentsOf: url.appendingPathComponent($0 + ".json"))) }
    }

    /// The JSON object a file or an encoding holds, for comparing bytes
    /// that differ only in whitespace and key order.
    private func object(_ data: Data) throws -> NSDictionary {
        try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? NSDictionary)
    }

    func testEveryDirectoryIsThere() {
        for dir in Self.expected.keys {
            var isDir: ObjCBool = false
            XCTAssertTrue(FileManager.default.fileExists(atPath: Self.root.appendingPathComponent(dir).path, isDirectory: &isDir) && isDir.boolValue,
                          "\(Self.root.path)/\(dir) is missing")
        }
    }

    func testServerMessagesDecode() throws {
        for (name, data) in try goldens("ws/server") {
            let m = try WSMessage.decode(data)
            XCTAssertTrue(name.hasPrefix(m.type.rawValue), "\(name) decoded as \(m.type)")
        }
        let ready = try WSMessage.decode(try XCTUnwrap(goldens("ws/server").first { $0.name == "bot-ready" }).data)
        XCTAssertEqual(ready.protocol, ProtocolHandshake.protocolVersion)
        XCTAssertTrue(ready.features?.contains(AgentScreenStream.ansiFeature) == true, "\(ready.features ?? [])")
        let screen = try WSMessage.decode(try XCTUnwrap(goldens("ws/server").first { $0.name == "screen" }).data)
        XCTAssertEqual(screen.screen?.ansi, true)
        XCTAssertNotNil(screen.screen?.stateSince, "a screen's state_since must decode as a date")
        let card = try WSMessage.decode(try XCTUnwrap(goldens("ws/server").first { $0.name == "card-approval" }).data)
        XCTAssertEqual(card.card?.options?.count, 2)
    }

    func testClientMessagesRoundTrip() throws {
        for (name, data) in try goldens("ws/client") {
            let m = try WSMessage.decode(data)
            XCTAssertTrue(name.hasPrefix(m.type.rawValue), "\(name) decoded as \(m.type)")
            XCTAssertEqual(try object(m.encode()), try object(data), "\(name): the app would send something else")
        }
    }

    func testTermMessagesRoundTrip() throws {
        for dir in ["term/server", "term/client"] {
            for (name, data) in try goldens(dir) {
                let m = try TermMessage.decode(data)
                XCTAssertEqual(m.type.rawValue, name.replacingOccurrences(of: "-shell", with: ""), name)
                XCTAssertEqual(try object(m.encode()), try object(data), "\(dir)/\(name)")
            }
        }
    }

    func testHelloDecodes() throws {
        let data = try XCTUnwrap(goldens("rest").first { $0.name == "hello" }).data
        let hello = try DaemonClient.decoder.decode(Hello.self, from: data)
        XCTAssertEqual(hello.protocol, ProtocolHandshake.protocolVersion)
        XCTAssertEqual(hello.ws, "/ws")
        XCTAssertEqual(hello.audio.inHz, 16000)
        XCTAssertNotNil(hello.computer, "the computer's id and name")
    }

    func testStateDecodes() throws {
        let data = try XCTUnwrap(goldens("rest").first { $0.name == "state" }).data
        let state = try DaemonClient.decoder.decode(DaemonState.self, from: data)
        XCTAssertEqual(state.agents.map(\.alias), ["auth", "docs"])
        XCTAssertNotNil(state.pendingAction)
        XCTAssertEqual(state.questions?.count, 1)
        XCTAssertEqual(state.questions?.first?.options?.count, 3)
        XCTAssertNotNil(state.brain)
        XCTAssertNotNil(state.conversationStartedAt)
    }
}
